 DROP FUNCTION IF EXISTS cjams.sp_gap_worksheet_extension_criteria_info(al_client_id bigint);
 
CREATE OR REPLACE FUNCTION cjams.sp_gap_worksheet_extension_criteria_info(al_client_id bigint)
 RETURNS TABLE(client_id bigint, childmeetcontinueeligibilitycriteria character varying, nameofsecondaryeducationorequivalentprogram character varying, startdateofsecondaryeducationorequivalentprogram timestamp without time zone, nameofpostsecondaryorvocationaleducation character varying, startdateofpostsecondaryorvocationaleducation timestamp without time zone, nameofpromotebarrierstoemploymentprogram character varying, startdateofpromotebarrierstoemploymentprogram timestamp without time zone, nameofemployer character varying, startdateofemployment timestamp without time zone, hourspermonthemployed integer, childdisabilitytype character varying, childdisabilitystartdate timestamp without time zone, childdisabilityevaluationdocumentiondate timestamp without time zone)
 LANGUAGE plpgsql
AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 vs_Procedure_nm                                                                 VARCHAR(100) DEFAULT 'sp_gap_worksheet_extension_criteria_info';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 vs_chld_meet_elig_crtria                                                VARCHAR(20);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 vs_scndry_edu_eqlnt_prgm                                                VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 vd_scndry_edu_eqlnt_prgm_strt_dt                                TIMESTAMP;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 vs_post_scndry_vctl_edu                                                 VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 vd_post_scndry_vctl_edu_strt_dt                                 TIMESTAMP;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 vs_prmtd_empl_prgm_nm                                                   VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 vd_prmtd_empl_prgm_strt_dt                                              TIMESTAMP;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 vs_empl_nm                                                                              VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 vd_empl_strt_dt                                                                 TIMESTAMP;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 vn_empl_hrs_mnth                                                                INTEGER;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 vs_chd_disablty_tp                                                              VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 vd_chd_disablty_strt_dt                                                 TIMESTAMP;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 vd_chd_disablty_evltn_docmntn_dt                                TIMESTAMP;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
  BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 CREATE TEMP TABLE IF NOT EXISTS                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 Temp_worksheet_eighteen_criteria_info (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 client_id                                                                                               BIGINT,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 childmeetcontinueeligibilitycriteria                                    VARCHAR(20),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 nameofsecondaryeducationorequivalentprogram                             VARCHAR(50),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 startdateofsecondaryeducationorequivalentprogram                TIMESTAMP,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 nameofpostsecondaryorvocationaleducation                                VARCHAR(50),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 startdateofpostsecondaryorvocationaleducation                   TIMESTAMP,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 nameofpromotebarrierstoemploymentprogram                                VARCHAR(50),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 startdateofpromotebarrierstoemploymentprogram                   TIMESTAMP,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 nameofemployer                                                                                  VARCHAR(50),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 startdateofemployment                                                                   TIMESTAMP,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 hourspermonthemployed                                                                   INTEGER,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 childdisabilitytype                                                                             VARCHAR(50),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 childdisabilitystartdate                                                                TIMESTAMP,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 childdisabilityevaluationdocumentiondate                                TIMESTAMP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 -- Child Meet Continue Eligibility Criteria                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 SELECT ( CASE WHEN (grd.childmeeteligcriteria = 1)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                 THEN 'YES'::VARCHAR ELSE 'NO'::VARCHAR END )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         INTO vs_chld_meet_elig_crtria                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         FROM guardianship grd, permanencyplan pp, servicecase sc, tb_placement tp, intakeservicerequestactor isra, person per                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 WHERE grd.servicecaseid = pp.servicecaseid AND grd.permanencyplanid = pp.permanencyplanid AND pp.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         AND pp.servicecaseid = sc.servicecaseid AND sc.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         AND tp.case_id = sc.servicecasenumber::BIGINT AND tp.delete_sw = 'N' AND tp.approval_status_cd = '3047'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         AND isra.intakeservicerequestactorid = tp.intakeservicerequestactorid AND isra.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         AND per.personid = isra.personid AND per.cjamspid::BIGINT = al_client_id AND per.activeflag = 1 ORDER BY grd.updatedon DESC LIMIT 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 -- Name Of Secondary Education/Equivalent Program  / Secondary Education/Equivalent Program Start Date / Name Of Post-Secondary/Vocational Education / Post-Secondary/Vocational Education Start Date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 SELECT ( CASE WHEN (rtrim(pedu.educationtypekey) = 'SECY' )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                 THEN ( SELECT typedescription                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                 FROM educationtype                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                 WHERE TRIM(educationtypekey)=TRIM(pedu.educationtypekey) )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                 ELSE NULL END ),
         ( CASE WHEN (rtrim(pedu.educationtypekey) = 'SECY' )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                 THEN ( SELECT pedu.startdate )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                 ELSE NULL END ),
                                 
         ( CASE WHEN (rtrim(pedu.educationtypekey) = 'PTSECY' )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         THEN ( SELECT typedescription                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                         FROM educationtype                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                         WHERE TRIM(educationtypekey)=TRIM(pedu.educationtypekey) )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         ELSE NULL END ),
         ( CASE WHEN (rtrim(pedu.educationtypekey) = 'PTSECY' )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                 THEN ( SELECT pedu.startdate )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                 ELSE NULL END ) 
         INTO vs_scndry_edu_eqlnt_prgm , vd_scndry_edu_eqlnt_prgm_strt_dt , vs_post_scndry_vctl_edu , vd_post_scndry_vctl_edu_strt_dt                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         FROM personeducation pedu, person per                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 WHERE per.personid = pedu.personid AND pedu.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         AND per.cjamspid::BIGINT = al_client_id AND per.activeflag = 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 -- Promoted Employment Program Name / -- Promoted Employment Program Start Date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 SELECT grd.empprogramname , grd.empprogramstartdate                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         INTO vs_prmtd_empl_prgm_nm , vd_prmtd_empl_prgm_strt_dt                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         FROM guardianship grd, permanencyplan pp, servicecase sc, tb_placement tp, intakeservicerequestactor isra, person per                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 WHERE grd.servicecaseid = pp.servicecaseid AND grd.permanencyplanid = pp.permanencyplanid AND pp.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         AND pp.servicecaseid = sc.servicecaseid AND sc.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         AND tp.case_id = sc.servicecasenumber::BIGINT AND tp.delete_sw = 'N' AND tp.approval_status_cd = '3047'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         AND isra.intakeservicerequestactorid = tp.intakeservicerequestactorid AND isra.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         AND per.personid = isra.personid AND per.cjamspid::BIGINT = al_client_id AND per.activeflag = 1 ORDER BY grd.updatedon DESC LIMIT 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 -- Employer Name  /  -- Employment Start Date / - Employed Hours/Month                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 SELECT pemp.employername , pemp.startdate , pemp.noofhours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         INTO vs_empl_nm , vd_empl_strt_dt , vn_empl_hrs_mnth                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         FROM personemployerdetail pemp, person per                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 WHERE per.personid = pemp.personid AND pemp.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         AND per.cjamspid::BIGINT = al_client_id AND per.activeflag = 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 -- Child Disability Type  / Child Disability Start Date  /  Child Disability Evaluation Documentation Date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 SELECT ( CASE WHEN (pdis.disabilityflag = 1)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                         THEN 'Permanent'::VARCHAR ELSE 'Temporary'::VARCHAR END )   , pdis.startdate  , pdis.evaluationdate                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         INTO vs_chd_disablty_tp , vd_chd_disablty_strt_dt , vd_chd_disablty_evltn_docmntn_dt                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         FROM persondisability pdis, person per                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 WHERE per.personid =  pdis.personid AND pdis.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         AND per.cjamspid::BIGINT = al_client_id AND per.activeflag = 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 INSERT INTO Temp_worksheet_eighteen_criteria_info                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 al_client_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 vs_chld_meet_elig_crtria,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 vs_scndry_edu_eqlnt_prgm,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 vd_scndry_edu_eqlnt_prgm_strt_dt,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 vs_post_scndry_vctl_edu,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 vd_post_scndry_vctl_edu_strt_dt,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 vs_prmtd_empl_prgm_nm,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 vd_prmtd_empl_prgm_strt_dt,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 vs_empl_nm,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 vd_empl_strt_dt,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 vn_empl_hrs_mnth,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 vs_chd_disablty_tp,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 vd_chd_disablty_strt_dt,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 vd_chd_disablty_evltn_docmntn_dt;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 RETURN QUERY SELECT *                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                FROM Temp_worksheet_eighteen_criteria_info;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 DROP TABLE Temp_worksheet_eighteen_criteria_info;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
    END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
     $function$
;